// Generates the sample content we own outright and copies in the two characters:
//   sets/cafe.glb, props/door-frame.glb   boxes with flat colours and KHR_physics colliders (@vrmxg/model's writer)
//   animations.json, animations/clips/    idle, walk, run, jump, fall, land and idle-sword, generated by our own
//                                         code and written with vrmxa-core's .vrma writer (CC0)
//   characters/mira.vrmxa, hana.vrmxa     vrmxa-core's full and minimal fixtures (Spec inside: VRM PL 1.0)
// Then puts the scenes in canonical form and validates them. Re-run to regenerate; the outputs are committed.
//   node content/sample/tools/make-content.mjs
import fs from 'node:fs';
import path from 'node:path';
import { writeGLB, writeGLBTree } from '@vrmxg/model';
import { packItem } from '@vrmxg/item';
import { m0Registry } from '@vrmxg/registry/m0';
import { createValidator, parse, serialize } from '@vrmxg/scene';

const root = path.resolve(import.meta.dirname, '..');
const dev = path.resolve(root, '../../..');
const write = (rel, bytes) => { fs.mkdirSync(path.dirname(path.join(root, rel)), { recursive: true }); fs.writeFileSync(path.join(root, rel), bytes); console.log('wrote', rel, bytes.length ?? '', 'bytes'); };
const GEN = 'VRMXG sample content (content/sample/tools/make-content.mjs)';

// ---------------------------------------------------------------- the cafe set
// A 12 × 12 m room centred on the origin, the entrance (a 2 m gap for the double door) in the south wall at
// z = 6, the staff door (1 m) in the east wall at z = -3, a pavement outside. Colliders on everything solid.
const C = { floor: '#b08a63', pave: '#9b9a96', wall: '#e9e1d4', trim: '#6b4a33', counter: '#5a3c28', top: '#d9cbb2', wood: '#8a5a3b', seat: '#3f6f73', shelf: '#7a5236', glass: '#a9cfe0', rug: '#9c3f36', lamp: '#fff1c9', plant: '#4f7d46', pot: '#b9714f' };
const parts = [
  { name: 'floor', size: [12, 0.2, 12], p: [0, -0.1, 0], color: C.floor, collider: true },
  { name: 'pavement', size: [16, 0.2, 8], p: [0, -0.1, 10], color: C.pave, collider: true },
  { name: 'wall-north', size: [12.4, 3, 0.2], p: [0, 1.5, -6.1], color: C.wall, collider: true },
  { name: 'wall-west', size: [0.2, 3, 12.4], p: [-6.1, 1.5, 0], color: C.wall, collider: true },
  { name: 'wall-east-a', size: [0.2, 3, 2.6], p: [6.1, 1.5, -4.8], color: C.wall, collider: true },
  { name: 'wall-east-b', size: [0.2, 3, 8.6], p: [6.1, 1.5, 1.8], color: C.wall, collider: true },
  { name: 'wall-east-lintel', size: [0.2, 0.75, 1], p: [6.1, 2.625, -3], color: C.wall, collider: true },
  { name: 'wall-south-a', size: [5.2, 3, 0.2], p: [-3.6, 1.5, 6.1], color: C.wall, collider: true },
  { name: 'wall-south-b', size: [5.2, 3, 0.2], p: [3.6, 1.5, 6.1], color: C.wall, collider: true },
  { name: 'wall-south-lintel', size: [2, 0.75, 0.2], p: [0, 2.625, 6.1], color: C.wall, collider: true },
  { name: 'skirting', size: [12, 0.12, 0.04], p: [0, 0.06, -5.98], color: C.trim },
  { name: 'window-west', size: [0.06, 1.2, 3], p: [-5.98, 1.6, 0], color: C.glass, roughness: 0.15 },
  { name: 'window-south-a', size: [2.4, 1.2, 0.06], p: [-3.6, 1.6, 5.98], color: C.glass, roughness: 0.15 },
  { name: 'window-south-b', size: [2.4, 1.2, 0.06], p: [3.6, 1.6, 5.98], color: C.glass, roughness: 0.15 },
  // the counter and the shelf behind it
  { name: 'counter', size: [4, 1, 0.7], p: [0, 0.5, -4.2], color: C.counter, collider: true },
  { name: 'counter-top', size: [4.1, 0.06, 0.8], p: [0, 1.03, -4.2], color: C.top, roughness: 0.4 },
  { name: 'shelf', size: [3.6, 0.05, 0.35], p: [0, 1.6, -5.82], color: C.shelf },
  { name: 'shelf-2', size: [3.6, 0.05, 0.35], p: [0, 2.1, -5.82], color: C.shelf },
  { name: 'rug', size: [3, 0.01, 2], p: [0, 0.005, 2.5], color: C.rug, roughness: 1 },
  { name: 'plant-pot', size: [0.5, 0.5, 0.5], p: [-5.4, 0.25, -5.4], color: C.pot, collider: true },
  { name: 'plant', size: [0.7, 0.9, 0.7], p: [-5.4, 0.95, -5.4], color: C.plant, roughness: 1 },
];
for (const [x, z] of [[-3, 1], [3, 1], [3, -2], [-3, -2.2]]) {
  parts.push({ name: `table-${x}-${z}`, size: [0.9, 0.05, 0.9], p: [x, 0.75, z], color: C.wood });
  parts.push({ name: `table-leg-${x}-${z}`, size: [0.1, 0.72, 0.1], p: [x, 0.36, z], color: C.trim });
  parts.push({ name: `table-col-${x}-${z}`, size: [0.9, 0.78, 0.9], p: [x, 0.39, z], color: C.wood, collider: true, visible: false });
}
// (the stools beside the tables are items now: items/stool.vrmxi, sat on with the sit verb, M1 W9)
for (const x of [-1.5, 0, 1.5]) parts.push({ name: `pendant-${x}`, size: [0.3, 0.12, 0.3], p: [x, 2.6, -4.2], color: C.lamp, roughness: 0.3 });
write('sets/cafe.glb', writeGLB({ name: 'cafe', generator: GEN, parts }));

// ---------------------------------------------------------------- the door frame (one door's width)
write('props/door-frame.glb', writeGLB({ name: 'door-frame', generator: GEN, parts: [
  // Posts clear of the hinge (door-local x -0.45) by 5 cm, so the swinging panel's corner never catches them.
  { name: 'post-left', size: [0.06, 2.2, 0.16], p: [-0.53, 1.1, 0], color: C.trim, collider: true },
  { name: 'post-right', size: [0.06, 2.2, 0.16], p: [0.53, 1.1, 0], color: C.trim, collider: true },
  { name: 'head', size: [1.12, 0.1, 0.16], p: [0, 2.2, 0], color: C.trim },
] }));

// ---------------------------------------------------------------- the door panel (seen; its collider is the prefab's)
write('props/door-panel.glb', writeGLB({ name: 'door-panel', generator: GEN, parts: [
  { name: 'panel', size: [0.88, 2, 0.04], p: [0, 0, 0], color: '#9a6b47', roughness: 0.6 },
  { name: 'window', size: [0.5, 0.7, 0.045], p: [0, 0.45, 0], color: C.glass, roughness: 0.15 },
  { name: 'handle', size: [0.12, 0.03, 0.08], p: [0.34, 0, 0], color: '#c9c3b6', metalness: 0.8, roughness: 0.3 },
] }));

// ---------------------------------------------------------------- the cafe door as a VRMXI game item (needs vrmxa-core to pack)
// A frame of three fixed box colliders, a dynamic leaf held by a hinge that swings both ways, a Reach sensor through
// the doorway, closed / open / locked states, open and close verbs (VRMXI-base-draft.md).
const box3 = (size) => ({ type: 'box', box: { size } });
const doorModel = () => writeGLBTree({ name: 'Cafe door', generator: GEN, roots: ['Door'], nodes: [
  { name: 'Door', children: ['Frame', 'Leaf', 'Reach'] },
  { name: 'Frame', children: ['Post left', 'Post right', 'Head'] },
  { name: 'Post left', t: [-0.53, 1.1, 0], box: { size: [0.06, 2.2, 0.16], color: C.trim }, collider: box3([0.06, 2.2, 0.16]) },
  { name: 'Post right', t: [0.53, 1.1, 0], box: { size: [0.06, 2.2, 0.16], color: C.trim }, collider: box3([0.06, 2.2, 0.16]) },
  { name: 'Head', t: [0, 2.2, 0], box: { size: [1.12, 0.1, 0.16], color: C.trim }, collider: box3([1.12, 0.1, 0.16]) },
  { name: 'Leaf', t: [0, 1.0, 0], motion: { mass: 12 }, children: ['Panel', 'Window', 'Handle'] },
  { name: 'Panel', box: { size: [0.88, 2, 0.04], color: '#9a6b47', roughness: 0.6 }, collider: box3([0.88, 2, 0.04]) },
  { name: 'Window', t: [0, 0.45, 0], box: { size: [0.5, 0.7, 0.045], color: C.glass, roughness: 0.15 } },
  { name: 'Handle', t: [0.34, 0, 0.04], box: { size: [0.12, 0.03, 0.08], color: '#c9c3b6', metalness: 0.8, roughness: 0.3 } },
  { name: 'Reach', t: [0, 1.0, 0], trigger: box3([1.2, 2.0, 2.4]) },
] });
const doorManifest = {
  format: 'vrmxi', version: 1, id: '5d6a8f1c-3b2e-4c7d-9a10-2f4e6b8c0d11', revision: 1, name: 'Cafe door',
  generator: GEN, type: 'door', tags: ['door:wood'], model: { file: 'model.glb' },
  joints: [{ name: 'hinge', type: 'hinge', body: 'Leaf', to: null, anchor: [-0.45, 1.0, 0], axis: [0, 1, 0], limits: { min: -1.75, max: 1.75 }, motor: { target: 0, stiffness: 400, damping: 60 } }],
  states: [
    { name: 'closed', tags: ['door:closed'], joints: { hinge: 0 } },
    { name: 'open', tags: ['door:open'], joints: { hinge: 1.6 } },
    { name: 'locked', tags: ['door:locked'], joints: { hinge: 0 } },
  ],
  verbs: [
    { verb: 'open', prompt: 'Open', states: ['closed'], to: 'open', reach: 'Reach' },
    { verb: 'open', prompt: 'Close', states: ['open'], to: 'closed', reach: 'Reach' },
  ],
  takeable: false, extensions: {},
  meta: { version: '1.0', authors: ['Xocialize LLC'], licenseUrl: 'https://vrm.dev/licenses/1.0/', commercialUsage: 'corporation', creditNotation: 'unnecessary', allowRedistribution: true, modification: 'allowModificationRedistribution' },
  listing: null, origin: { made: 'authored', source: 'content/sample/tools/make-content.mjs' }, madeWith: null, thumbnail: null, files: [],
};

// ---------------------------------------------------------------- a cupboard (M1 W9): a VRMXI container with a hinged door
// Carcass of fixed boxes against a wall (front +z, origin on the floor), one door leaf on a hinge at its left edge that
// opens outwards, a mug on the shelf, a Reach sensor in front; closed / open states, open and close verbs.
const cupboardModel = () => writeGLBTree({ name: 'Cupboard', generator: GEN, roots: ['Cupboard'], nodes: [
  { name: 'Cupboard', children: ['Carcass', 'Door', 'Mug', 'Reach'] },
  { name: 'Carcass', children: ['Back', 'Side left', 'Side right', 'Top', 'Bottom', 'Shelf'] },
  { name: 'Back', t: [0, 0.9, -0.215], box: { size: [0.9, 1.8, 0.02], color: C.shelf }, collider: box3([0.9, 1.8, 0.02]) },
  { name: 'Side left', t: [-0.44, 0.9, 0], box: { size: [0.02, 1.8, 0.45], color: C.wood }, collider: box3([0.02, 1.8, 0.45]) },
  { name: 'Side right', t: [0.44, 0.9, 0], box: { size: [0.02, 1.8, 0.45], color: C.wood }, collider: box3([0.02, 1.8, 0.45]) },
  { name: 'Top', t: [0, 1.79, 0], box: { size: [0.9, 0.02, 0.45], color: C.wood }, collider: box3([0.9, 0.02, 0.45]) },
  { name: 'Bottom', t: [0, 0.05, 0], box: { size: [0.9, 0.1, 0.45], color: C.trim }, collider: box3([0.9, 0.1, 0.45]) },
  { name: 'Shelf', t: [0, 0.95, 0], box: { size: [0.86, 0.02, 0.42], color: C.shelf } },
  { name: 'Door', t: [0, 0.92, 0.235], motion: { mass: 4 }, children: ['Leaf', 'Knob'] },
  { name: 'Leaf', box: { size: [0.86, 1.64, 0.02], color: '#8f6242', roughness: 0.6 }, collider: box3([0.86, 1.64, 0.02]) },
  { name: 'Knob', t: [0.36, 0, 0.03], box: { size: [0.04, 0.04, 0.04], color: '#c9c3b6', metalness: 0.8, roughness: 0.3 } },
  { name: 'Mug', t: [0.1, 1.01, 0], box: { size: [0.09, 0.1, 0.09], color: '#e8e4dc', roughness: 0.4 } },
  { name: 'Reach', t: [0, 0.9, 0.8], trigger: box3([1.2, 1.8, 1.1]) },
] });
const cupboardManifest = {
  format: 'vrmxi', version: 1, id: '8e2c4a6b-1d3f-4e5a-b7c9-0a1b2c3d4e5f', revision: 1, name: 'Cupboard',
  generator: GEN, type: 'container', tags: ['container:cupboard'], model: { file: 'model.glb' },
  joints: [{ name: 'hinge', type: 'hinge', body: 'Door', to: null, anchor: [-0.43, 0.92, 0.235], axis: [0, 1, 0], limits: { min: -1.9, max: 0 }, motor: { target: 0, stiffness: 120, damping: 20 } }],
  states: [
    { name: 'closed', tags: ['cupboard:closed'], joints: { hinge: 0 } },
    { name: 'open', tags: ['cupboard:open'], joints: { hinge: -1.6 } },
  ],
  verbs: [
    { verb: 'open', prompt: 'Open', states: ['closed'], to: 'open', reach: 'Reach' },
    { verb: 'open', prompt: 'Close', states: ['open'], to: 'closed', reach: 'Reach' },
  ],
  takeable: false, extensions: {},
  meta: { version: '1.0', authors: ['Xocialize LLC'], licenseUrl: 'https://vrm.dev/licenses/1.0/', commercialUsage: 'corporation', creditNotation: 'unnecessary', allowRedistribution: true, modification: 'allowModificationRedistribution' },
  listing: null, origin: { made: 'authored', source: 'content/sample/tools/make-content.mjs' }, madeWith: null, thumbnail: null, files: [],
};

// ---------------------------------------------------------------- characters and clips (need the sibling repos)
const studio = path.join(dev, 'vrmxa-avatar-studio/packages/vrmxa-core');
if (fs.existsSync(studio)) {
  write('characters/mira.vrmxa', fs.readFileSync(path.join(studio, 'fixtures/characters/full.vrmxa')));
  write('characters/hana.vrmxa', fs.readFileSync(path.join(studio, 'fixtures/characters/minimal.vrmxa')));
  const { vrmxaCore, testAnimations } = await import(path.join(root, '../../engine/packages/character/test/fixtures.mjs'));
  const a = await testAnimations(await vrmxaCore(), { travel: true, actions: true, layers: true, emotes: true }); // walk and run carry root motion (M0 check 2); use / equip / talk / sit / sitIdle / stand for items (M1 W3); the sword's hold and a greet wave as masked layers (M2 W8, G10)
  const byName = new Map(a.doc.clips.map((c) => [c.sha256, c.name]));
  for (const [sha, bytes] of a.clips) write(`animations/clips/${byName.get(sha)}.vrma`, bytes);
  // The sword set follows a sword in hand (VRMXA §8.3, a state's tags): Mira's own sword is stowed, so her idle
  // changes when she takes the sword on the table (or draws hers).
  const sets = a.doc.sets.map((s) => (s.id === 'sword' ? { ...s, requires: ['held:sword'] } : s));
  const doc = { ...a.doc, sets, clips: a.doc.clips.map((c) => ({ ...c, licence: 'CC0-1.0', source: 'generated by engine/packages/character/test/fixtures.mjs' })) };
  write('animations.json', JSON.stringify(doc, null, 1) + '\n');
  const door = await packItem({ manifest: doorManifest, model: doorModel(), vrmxaCore: await vrmxaCore() });
  // checked by the specification's own checker when VRMXA_Specification (with the VRMXI draft) is beside the repo
  const { SPEC, specChecker } = await import(path.join(root, '../../engine/packages/item/test/fixtures.mjs'));
  if (SPEC) { const found = (await specChecker())(door).filter((p) => p.severity === 'error'); if (found.length) throw new Error(`items/cafe-door.vrmxi: ${JSON.stringify(found)}`); console.log('valid items/cafe-door.vrmxi (VRMXI checker)'); }
  write('items/cafe-door.vrmxi', door);
  const cupboard = await packItem({ manifest: cupboardManifest, model: cupboardModel(), vrmxaCore: await vrmxaCore() });
  if (SPEC) { const found = (await specChecker())(cupboard).filter((p) => p.severity === 'error'); if (found.length) throw new Error(`items/cupboard.vrmxi: ${JSON.stringify(found)}`); console.log('valid items/cupboard.vrmxi (VRMXI checker)'); }
  write('items/cupboard.vrmxi', cupboard);
  // the specification's sword pickup (takeable, embeds a pinned "Short sword", put on held), byte for byte
  if (SPEC) write('items/sword-pickup.vrmxi', fs.readFileSync(path.join(SPEC, 'fixtures-vrmxi/items/sword-pickup.vrmxi')));
  // and its light switch (off / on, a use verb each way), byte for byte
  if (SPEC) write('items/switch.vrmxi', fs.readFileSync(path.join(SPEC, 'fixtures-vrmxi/items/switch.vrmxi')));
  // and its stool (a seat: sit, with a seat point and an exit), byte for byte: the cafe's stools (M1 W9)
  if (SPEC) write('items/stool.vrmxi', fs.readFileSync(path.join(SPEC, 'fixtures-vrmxi/items/stool.vrmxi')));
} else console.log('vrmxa-avatar-studio not beside the repo: characters and clips left as committed');

// ---------------------------------------------------------------- scenes: canonical form, validated
const reg = m0Registry(), { check } = createValidator(reg);
const prefabs = new Map();
for (const f of ['prefabs/door.vrmxs', 'prefabs/double-door.vrmxs']) prefabs.set(f, parse(fs.readFileSync(path.join(root, f), 'utf8')));
for (const f of ['prefabs/door.vrmxs', 'prefabs/double-door.vrmxs', 'cafe.vrmxs']) {
  const doc = parse(fs.readFileSync(path.join(root, f), 'utf8'));
  const r = check(doc, { prefabs });
  if (!r.ok) throw new Error(`${f}: ${r.errors.join('\n')}`);
  fs.writeFileSync(path.join(root, f), serialize(doc));
  console.log('valid', f, r.warnings.length ? `(${r.warnings.length} warnings: ${r.warnings.join('; ')})` : '');
}
